import{_ as n,o as s,c as t,ai as e}from"./chunks/framework.BxxKhjs3.js";const o="/pub-blog/assets/image-20260506170830493.Nq4u0uRa.png",p="/pub-blog/assets/image-20260506170947308.YUjhgN3I.png",r="/pub-blog/assets/image-20260506172640597.CxnJCBQd.png",i="/pub-blog/assets/image-20260506172653937.D4bsjplR.png",l="/pub-blog/assets/image-20260506172809676.BUORGSW0.png",m="/pub-blog/assets/image-20260506171201989.BTedjLv2.png",g="/pub-blog/assets/image-20260506171254434.LuDAjiiY.png",b="/pub-blog/assets/image-20260506171344830.GGMV5aCk.png",c="/pub-blog/assets/image-20260506172602587.B3sfWH55.png",_="/pub-blog/assets/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.KtucpRsB.jpg",d="/pub-blog/assets/image-20260506171849746.DZJgeWZQ.png",h="/pub-blog/assets/image-20260506172925464.BPBe5mNM.png",E=JSON.parse('{"title":"万少的HarmonyOS知识库更新了","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/万少的HarmonyOS知识库更新了/万少的HarmonyOS知识库更新了.md","filePath":"鸿蒙开发技巧/万少的HarmonyOS知识库更新了/万少的HarmonyOS知识库更新了.md","lastUpdated":1778061314000,"__rawMarkdown":"# 万少的HarmonyOS知识库更新了\\n\\n> 万少：华为HDE、鸿蒙极客\\n>\\n> 个人主页：https://blog.zbztb.cn/\\n>\\n> **2025年参与孵化了20+鸿蒙应用、技术文章300+、鸿蒙知识库用户500+、鸿蒙免费课程2套。**\\n>\\n> 如果你也喜欢交流AI和鸿蒙技术，欢迎扣我。\\n\\n## 前言\\n\\n![](assets/image-20260506170830493.png)\\n\\n​\\t这次知识库的更新对标 HarmonyOS官网 6.1.0（23）Release版本。总共更新了**13318**个文件。\\n\\n![](assets/image-20260506170947308.png)\\n\\n我为什么一直坚持使用ima内的HarmonyOS知识库，主要原因无他：**方便；**\\n\\n1. 你可以直接在微信的小程序中使用\\n\\n2. 也可以下载单独的客户端在电脑上使用\\n\\n3. 目前的知识库还支持接入腾讯系的**龙虾** **QCLAW**，里面让你的龙虾具有无限数据的能力；\\n\\n   ![](assets/image-20260506172640597.png)\\n\\n   ![](assets/image-20260506172653937.png)\\n\\n   4. 最近的ima也支持了copilot能力（需要申请），它可以让你的数据**活起来**\\n\\n      ![](assets/image-20260506172809676.png)\\n\\n   ---\\n\\n   \\n\\n使用自然语言获取相关的鸿蒙信息后，也可以提取成md文档，然后喂给你的AI编程工具使用。\\n\\n这就是知识库得到很多人喜欢使用的原因；\\n\\n![](assets/image-20260506171201989.png)\\n\\n\\n\\n![](assets/image-20260506171254434.png)\\n\\n\\n\\n## 如何使用\\n\\n1. 打开链接\\n\\n   > 【ima知识库】鸿蒙应用知识库HarmonyOS6 https://ima.qq.com/wiki/?shareId=b0d462ae618a0fefb5b714565cad3dd4a60411a435d5f81db51670ffb2ff3ad7\\n\\n2. 微信扫码\\n\\n   > ![](assets/image-20260506171344830.png)\\n\\n\\n3. 使用自然语言进行对话\\n\\n   ![](assets/image-20260506172602587.png)\\n\\n   \\n\\n\\n\\n## 关于我 \\n\\n我建立了一个鸿蒙技术开发交流群，已经满200人了，欢迎进群进行技术沟通；\\n\\n![](assets/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.jpg)\\n\\n\\n\\n## 另外\\n\\n目前开发鸿蒙技术，也是需要结合AI来提效，万少也专门录制一套**AI提效鸿蒙开发课**，有需要的小伙伴可以购买订阅，享受万少的1对1AI提效鸿蒙辅导；\\n\\n课程包含5个多小时的AI+鸿蒙能力；\\n\\n包括使用Trae 、智能体、rules、skill等常用的AI技巧；\\n\\n包括HarmonyOS的自动化语法检测，让你一次对话，就能生成正确的代码，杜绝语法幻觉；\\n\\n结合智谱AI能力，批量0成本生成图片素材、视频素材。\\n\\n> https://www.bilibili.com/cheese/play/ss832248878\\n\\n![](assets/image-20260506171849746.png)\\n\\n![](assets/image-20260506172925464.png)"}'),f={name:"鸿蒙开发技巧/万少的HarmonyOS知识库更新了/万少的HarmonyOS知识库更新了.md"};function u(A,a,k,q,S,y){return s(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="万少的harmonyos知识库更新了" tabindex="-1">万少的HarmonyOS知识库更新了 <a class="header-anchor" href="#万少的harmonyos知识库更新了" aria-label="Permalink to &quot;万少的HarmonyOS知识库更新了&quot;">​</a></h1><blockquote><p>万少：华为HDE、鸿蒙极客</p><p>个人主页：<a href="https://blog.zbztb.cn/" target="_blank" rel="noreferrer">https://blog.zbztb.cn/</a></p><p><strong>2025年参与孵化了20+鸿蒙应用、技术文章300+、鸿蒙知识库用户500+、鸿蒙免费课程2套。</strong></p><p>如果你也喜欢交流AI和鸿蒙技术，欢迎扣我。</p></blockquote><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p><img src="'+o+'" alt=""></p><p>​ 这次知识库的更新对标 HarmonyOS官网 6.1.0（23）Release版本。总共更新了<strong>13318</strong>个文件。</p><p><img src="'+p+'" alt=""></p><p>我为什么一直坚持使用ima内的HarmonyOS知识库，主要原因无他：<strong>方便；</strong></p><ol><li><p>你可以直接在微信的小程序中使用</p></li><li><p>也可以下载单独的客户端在电脑上使用</p></li><li><p>目前的知识库还支持接入腾讯系的<strong>龙虾</strong> <strong>QCLAW</strong>，里面让你的龙虾具有无限数据的能力；</p><p><img src="'+r+'" alt=""></p><p><img src="'+i+'" alt=""></p><ol start="4"><li><p>最近的ima也支持了copilot能力（需要申请），它可以让你的数据<strong>活起来</strong></p><p><img src="'+l+'" alt=""></p></li></ol><hr></li></ol><p>使用自然语言获取相关的鸿蒙信息后，也可以提取成md文档，然后喂给你的AI编程工具使用。</p><p>这就是知识库得到很多人喜欢使用的原因；</p><p><img src="'+m+'" alt=""></p><p><img src="'+g+'" alt=""></p><h2 id="如何使用" tabindex="-1">如何使用 <a class="header-anchor" href="#如何使用" aria-label="Permalink to &quot;如何使用&quot;">​</a></h2><ol><li><p>打开链接</p><blockquote><p>【ima知识库】鸿蒙应用知识库HarmonyOS6 <a href="https://ima.qq.com/wiki/?shareId=b0d462ae618a0fefb5b714565cad3dd4a60411a435d5f81db51670ffb2ff3ad7" target="_blank" rel="noreferrer">https://ima.qq.com/wiki/?shareId=b0d462ae618a0fefb5b714565cad3dd4a60411a435d5f81db51670ffb2ff3ad7</a></p></blockquote></li><li><p>微信扫码</p><blockquote><p><img src="'+b+'" alt=""></p></blockquote></li><li><p>使用自然语言进行对话</p><p><img src="'+c+'" alt=""></p></li></ol><h2 id="关于我" tabindex="-1">关于我 <a class="header-anchor" href="#关于我" aria-label="Permalink to &quot;关于我&quot;">​</a></h2><p>我建立了一个鸿蒙技术开发交流群，已经满200人了，欢迎进群进行技术沟通；</p><p><img src="'+_+'" alt=""></p><h2 id="另外" tabindex="-1">另外 <a class="header-anchor" href="#另外" aria-label="Permalink to &quot;另外&quot;">​</a></h2><p>目前开发鸿蒙技术，也是需要结合AI来提效，万少也专门录制一套<strong>AI提效鸿蒙开发课</strong>，有需要的小伙伴可以购买订阅，享受万少的1对1AI提效鸿蒙辅导；</p><p>课程包含5个多小时的AI+鸿蒙能力；</p><p>包括使用Trae 、智能体、rules、skill等常用的AI技巧；</p><p>包括HarmonyOS的自动化语法检测，让你一次对话，就能生成正确的代码，杜绝语法幻觉；</p><p>结合智谱AI能力，批量0成本生成图片素材、视频素材。</p><blockquote><p><a href="https://www.bilibili.com/cheese/play/ss832248878" target="_blank" rel="noreferrer">https://www.bilibili.com/cheese/play/ss832248878</a></p></blockquote><p><img src="'+d+'" alt=""></p><p><img src="'+h+'" alt=""></p>',26)])])}const H=n(f,[["render",u]]);export{E as __pageData,H as default};
